#!/usr/bin/env bash
# Builds epx release archives. Run inside a checkout; .github/workflows/release.yml runs
# it for every pushed vMAJOR.MINOR.PATCH tag.
#
#   .github/scripts/release.sh             tagged release: HEAD must carry a canonical vMAJOR.MINOR.PATCH
#                                  tag and the tree must be clean (no modified or untracked files)
#   .github/scripts/release.sh --snapshot  any commit, for testing
#   .github/scripts/release.sh --publish   tagged release, then `gh release create` with the
#                                  archives and the installers (install/install.sh,
#                                  install/install.ps1, served as
#                                  releases/latest/download/install.{sh,ps1}), once the remote
#                                  tag is verified to name the built commit. The maintainer
#                                  writes the release notes into the annotated tag (its
#                                  message body); a tag without one gets notes generated by
#                                  GitHub. A release that exists already (a rerun) is kept
#                                  when it is published and holds exactly the files built
#                                  here, byte for byte, so the workflow goes on to npm;
#                                  otherwise the run fails
#
# Binaries are static (CGO_ENABLED=0), built with -trimpath and VCS stamping, so
# `epx version` reports the tag without ldflags. Every binary is checked with
# `go version -m` (module version, revision, unmodified tree) before packaging.
# Archives are reproducible: their files carry the commit's time, fixed modes and owner 0,
# in a fixed order, and gzip stores no time, so a rebuild of the same commit on the same
# kind of builder, by any account and umask, has the same checksums. Tarballs need GNU tar
# (gtar where tar is another one, as on macOS: brew install gnu-tar).
# The tarballs (macOS and Linux) also hold the man pages, in man/.
# Output: dist/<version>/epx_<version>_<os>_<arch>.{tar.gz,zip} and a checksums file.
set -euo pipefail

fail() { echo "release: $*" >&2; exit 1; }

mode=${1:-release}
case $mode in release | --snapshot | --publish) ;; *) echo "usage: $0 [--snapshot|--publish]" >&2; exit 2 ;; esac
cd "$(git rev-parse --show-toplevel)"
commit=$(git rev-parse HEAD)

if [[ "$mode" = --snapshot ]]; then
	version=snapshot-$(git rev-parse --short HEAD)
else
	status=$(git status --porcelain) || fail "git status failed"
	[[ -z "$status" ]] || fail "the tree has modified or untracked files"
	version=$(git describe --exact-match --tags HEAD 2>/dev/null) || fail "HEAD has no tag"
	[[ $version =~ ^v(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)$ ]] ||
		fail "tag $version is not a canonical vMAJOR.MINOR.PATCH"
fi

out=dist/$version
[[ ! -e "$out" ]] || fail "$out already exists"
mkdir -p "$out"
stage=$(mktemp -d)
trap 'rm -r "$stage"' EXIT

# check_binary verifies the build info a binary carries.
check_binary() {
	local binary=$1 info
	info=$(go version -m "$binary") || fail "cannot read build info of $binary"
	grep -q "vcs.revision=$commit" <<<"$info" || fail "$binary was not built from $commit"
	if [[ "$mode" != --snapshot ]]; then
		grep -q "vcs.modified=false" <<<"$info" || fail "$binary was built from a modified tree"
		awk '$1 == "mod" { print $3 }' <<<"$info" | grep -qx "$version" || fail "$binary does not report $version"
	fi
}

# GNU tar, which stores no extended attributes by default (bsdtar stores some, such as
# com.apple.provenance, that GNU tar warns about when extracting).
gnu_tar=tar
tar --version 2>/dev/null | grep -q 'GNU tar' || gnu_tar=gtar
"$gnu_tar" --version 2>/dev/null | grep -q 'GNU tar' || fail "GNU tar is required (on macOS: brew install gnu-tar)"

# stamp is the commit's time (UTC, as touch -t takes it), which every archived file
# carries; zip stores times in local time, so the archives are made in UTC.
stamp=$(TZ=UTC git show -s --date=format-local:%Y%m%d%H%M.%S --format=%cd HEAD)
export TZ=UTC

# The man pages (man/*.1, generated from the command tree) go into the tarballs, their
# title lines dated with the commit's day and naming the version, as man shows in the footer.
day=$(git show -s --date=format-local:%Y-%m-%d --format=%cd HEAD)
mkdir "$stage/man"
for page in man/*.1; do
	sed "1s/^\(\.TH \"[^\"]*\" \"1\"\) \"\" \"epx\"/\1 \"$day\" \"epx $version\"/" "$page" >"$stage/man/${page#man/}"
	grep -q "^\.TH .* \"$day\" \"epx $version\"" "$stage/man/${page#man/}" || fail "$page has no title line to date"
done
pages=("$stage"/man/*.1)
[[ ${#pages[@]} -gt 1 ]] || fail "man/ holds no man pages"

for target in darwin/amd64 darwin/arm64 linux/amd64 linux/arm64 windows/amd64 windows/arm64; do
	os=${target%/*}
	arch=${target#*/}
	name=epx_${version}_${os}_${arch}
	exe=epx
	[[ "$os" = windows ]] && exe=epx.exe
	mkdir "$stage/$name"
	CGO_ENABLED=0 GOOS=$os GOARCH=$arch go build -buildvcs=true -trimpath -ldflags='-s -w' \
		-o "$stage/$name/$exe" ./cmd/epx
	check_binary "$stage/$name/$exe"
	cp LICENSE README.md "$stage/$name/"
	files=("$name" "$name/$exe" "$name/LICENSE" "$name/README.md")
	(cd "$stage" && chmod 755 "$name" "$name/$exe" && chmod 644 "$name/LICENSE" "$name/README.md")
	if [[ "$os" != windows ]]; then
		cp -R "$stage/man" "$stage/$name/man"
		chmod 755 "$stage/$name/man"
		files+=("$name/man")
		for page in "${pages[@]}"; do
			chmod 644 "$stage/$name/man/${page##*/}"
			files+=("$name/man/${page##*/}")
		done
	fi
	(cd "$stage" && touch -t "$stamp" "${files[@]}")
	if [[ "$os" = windows ]]; then
		# -X: no extra fields, such as the owner's UID and GID.
		(cd "$stage" && zip -qX "$OLDPWD/$out/$name.zip" "${files[@]}")
	else
		"$gnu_tar" --format=gnu --owner=0 --group=0 --numeric-owner --no-recursion \
			-C "$stage" -cf - "${files[@]}" | gzip -n >"$out/$name.tar.gz"
	fi
done
(cd "$out" && shasum -a 256 epx_* >"epx_${version}_checksums.txt")

host=$stage/epx_${version}_$(go env GOHOSTOS)_$(go env GOHOSTARCH)/epx
reported=$("$host" version) || fail "the host binary does not run"
echo "release: built $out ($reported)"
ls -1 "$out"

# installers are published beside the archives, served as releases/latest/download/<name>.
installers=(install/install.sh install/install.ps1)

# released reports whether the GitHub release of the version exists (1 only where gh
# says it is not found; any other failure of gh fails the run): then it must be published
# and hold exactly the archives, checksums file and installers built here, or the run
# fails, since a release is never replaced.
released() {
	local sums=epx_${version}_checksums.txt fetched=$stage/released draft want got installer
	if ! draft=$(gh release view "$version" --json isDraft --jq .isDraft 2>"$stage/gh.err"); then
		grep -q 'release not found' "$stage/gh.err" && return 1
		fail "cannot read release $version: $(cat "$stage/gh.err")"
	fi
	[[ "$draft" = false ]] ||
		fail "release $version is a draft (a run stopped while uploading); delete it and run again"
	mkdir "$fetched" || fail "cannot create $fetched"
	gh release download "$version" --dir "$fetched" || fail "cannot download the files of release $version"
	want=$({ ls "$out" && for installer in "${installers[@]}"; do basename "$installer"; done; } | LC_ALL=C sort)
	got=$(ls "$fetched" | LC_ALL=C sort)
	[[ "$got" = "$want" ]] || fail "release $version holds $(xargs <<<"$got"), not $(xargs <<<"$want")"
	cmp -s "$fetched/$sums" "$out/$sums" ||
		fail "release $version has another $sums than the one built from $commit"
	(cd "$fetched" && shasum -a 256 --check --quiet "$sums") ||
		fail "release $version holds other archives than those built from $commit"
	for installer in "${installers[@]}"; do
		cmp -s "$installer" "$fetched/$(basename "$installer")" ||
			fail "release $version holds another $(basename "$installer") than $commit"
	done
}

# notes prints the flag that chooses the release notes: the annotated tag's message where
# it has a body (gh takes a lightweight tag's commit message instead, so only an annotated
# tag counts), else notes that GitHub generates. refs, origin's lines of the tag, show
# whether it is annotated there (a peeled ^{} line); a local copy that is not fails.
notes() {
	local refs=$1 annotated=false
	[[ "$(git cat-file -t "refs/tags/$version")" = tag ]] && annotated=true
	if grep -q '\^{}$' <<<"$refs" && [[ "$annotated" = false ]]; then
		fail "origin's tag $version is annotated but the local one is not; git fetch --force origin tag $version"
	fi
	if [[ "$annotated" = true && -n "$(git tag -l --format='%(contents:body)' "$version")" ]]; then
		echo --notes-from-tag
	else
		echo --generate-notes
	fi
}

if [[ "$mode" = --publish ]]; then
	refs=$(git ls-remote origin "refs/tags/$version" "refs/tags/$version^{}")
	remote=$(awk '{ c = $1 } END { print c }' <<<"$refs")
	[[ "$remote" = "$commit" ]] || fail "origin's tag $version does not name $commit; push the tag first"
	if released; then
		echo "release: $version is already released with these archives"
	else
		notes_flag=$(notes "$refs")
		gh release create "$version" "$out"/* "${installers[@]}" \
			--verify-tag --title "$version" "$notes_flag"
	fi
fi
